import java.io.*;

public class Main {
    public static void main(String[] args) throws IOException {
        DataInputStream in = new DataInputStream(new BufferedInputStream(System.in, 1 << 16));
        int N = nextInt(in);
        int[] h = new int[N];
        int count = 0;
        // lê todas as alturas disponíveis (ex.: ex. 2 tem menos alturas que N)
        while (count < N) {
            int v = nextInt(in);
            if (v == -1) break;
            h[count++] = v;
        }
        int n = count;
        if (n == 0) { System.out.println(0); return; }

        int[] leftMax = new int[n];
        int[] rightMax = new int[n];
        leftMax[0] = h[0];
        for (int i = 1; i < n; i++) leftMax[i] = Math.max(leftMax[i - 1], h[i]);
        rightMax[n - 1] = h[n - 1];
        for (int i = n - 2; i >= 0; i--) rightMax[i] = Math.max(rightMax[i + 1], h[i]);

        long ans = 0;
        for (int i = 0; i < n; i++) {
            int level = Math.min(leftMax[i], rightMax[i]);
            if (level - h[i] >= 1) ans++;
        }
        System.out.println(ans);
    }

    private static int nextInt(DataInputStream in) throws IOException {
        int ret = 0, b;
        boolean neg = false;
        do { b = in.read(); if (b == -1) return -1; } while (b != '-' && (b < '0' || b > '9'));
        if (b == '-') neg = true;
        else ret = b - '0';
        while ((b = in.read()) >= '0' && b <= '9') ret = ret * 10 + (b - '0');
        return neg ? -ret : ret;
    }
}
